use vstd::prelude::*;

verus! {

fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        // Same length as input
        result@.len() == a@.len(),
        // Exact reverse relationship
        forall|i: int|
            0 <= i < result@.len() ==>
                result@[i] == a@[a@.len() - 1 - i],
        // Fresh vector value is fully determined by input
        result@ == a@.reverse(),
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            0 <= i <= a@.len(),
            result@.len() == i,
            forall|j: int|
                0 <= j < i ==>
                    result@[j] == a@[a@.len() - 1 - j],
    {
        let idx: usize = a.len() - 1 - i;
        result.push(a[idx]);
        i += 1;
    }

    // Establish the final sequence equality succinctly.
    assert(result@ == a@.reverse());

    result
}

} // verus!